    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    desperate_count = 0
    rich_aggressive = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            if opp.get('budget', 0) >= 500:
                prev = opp.get('previous_trace', {}) or {}
                pb = prev.get('bid')
                if pb is not None and pb >= 90:
                    rich_aggressive += 1
            prev = opp.get('previous_trace', {}) or {}
            pb = prev.get('bid')
            if pb is not None:
                prev_bids.append(pb)

    if not alive:
        return float(min(budget, 10.0))

    units = int(supply // WATER_REQ)
    if units < 1:
        units = 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    emergency = hp <= 2 or no_water_days >= 2
    fragile = hp <= 4 or no_water_days >= 1
    tight_supply = units == 1

    if emergency:
        bid = max(98.0, highest_prev + 3.0)
        return float(min(budget, bid))

    if tight_supply:
        if fragile:
            bid = max(92.0, highest_prev + 2.0)
        else:
            if highest_prev >= 130:
                bid = 36.0
            elif highest_prev >= 100:
                bid = 52.0
            else:
                bid = max(58.0, avg_prev * 0.9)

        if desperate_count >= 2:
            bid += 12.0
        elif desperate_count == 1:
            bid += 6.0

        return float(min(budget, bid))

    bid = 24.0
    if fragile:
        bid = 48.0
    if highest_prev < 70:
        bid = max(bid, highest_prev + 2.0)
    if desperate_count >= 2:
        bid += 10.0
    if rich_aggressive >= 2 and not fragile:
        bid = min(bid, 28.0)

    if hp >= 8 and budget < 140:
        bid = min(bid, 22.0)

    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = int(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for k, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    # If alone, bid to ensure water.
    if not alive_opps:
        target = DAILY_SALARY * 0.35
        return min(budget, max(0.0, target))

    # Read yesterday bids to infer aggressiveness.
    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    # Pressure tiers: exploit that some agents overbid; we undercut unless we are at risk.
    # Estimate how many water units are likely needed: if supply is near WATER_REQ, contest matters more.
    supply_ratio = supply / float(WATER_REQ)

    # Base bid depends on my hp and no-water streak.
    risk = 0
    if hp <= 2:
        risk = 2
    elif hp <= 4:
        risk = 1
    if no_water_days >= 2:
        risk = max(risk, 1)

    # Determine aggressiveness threshold from yesterday.
    # Yesterday top bids were around 138.6; bid slightly below that ceiling when safe.
    if highest_prev >= DAILY_SALARY * 0.85:
        # Aggressive field.
        if risk >= 2:
            target = avg_prev * 0.95
        else:
            target = min(highest_prev - 3.0, avg_prev * 0.75)
    else:
        # Not extremely aggressive.
        if risk >= 2:
            target = avg_prev * 0.9
        else:
            # If supply is tight, increase a bit.
            tight_bonus = 10.0 if supply_ratio <= (float(MIN_SUPPLY) / float(WATER_REQ)) else 0.0
            target = max(DAILY_SALARY * 0.45, avg_prev * 0.6) + tight_bonus

    # Keep bid within budget and sensible bounds.
    # Also, if budget is low, scale down.
    if budget <= DAILY_SALARY * 0.2:
        target = budget * 0.9
    elif budget <= DAILY_SALARY * 0.5:
        target = min(target, budget * 0.6)
    else:
        target = min(target, budget * 0.75)

    # Ensure non-negative.
    if target < 0.0:
        target = 0.0

    return float(target)

